		toggleMultibet: function toggleMultibet(visible) {
			if (window.tutorial_enabled && visible == false) return;
			this.isActive = visible;
			var gameName = document.getElementsByClassName('game-range-sel');
			if (visible) {
				//show

				$(gameName[0]).animate({
					'right': '81.5%'
				}, 200);
				$(gameName[1]).animate({
					'right': '81.5%'
				}, 200);
				$(gameName[2]).animate({
					'right': '0%'
				}, 200);
				$(gameName[3]).animate({
					'right': '0%'
				}, 200);

				createjs.Tween.get(this.bar).to({
					x: 0
				}, 200);
				createjs.Tween.get(this.multi_left).to({
					x: 0
				}, 200);

				createjs.Tween.get(this.bar2).to({
					x: this.context.stage.baseWidth - 355
				}, 200);
				createjs.Tween.get(this.multi_right).to({
					x: this.context.stage.baseWidth - 355
				}, 200);

				setTimeout(function () {
					$(".multibet-win-notif").show();
				}, 200);
			} else {
				// hide

				$('#roadmap-container').hide();
				$('.game-list').hide();
				this.toSwitchRoom = null;

				if (this.eyeRoadmap) {
					this.eyeRoadmap.eye.removeAllChildren();
					this.eyeRoadmap = null;
				}
				$(gameName[0]).animate({
					'right': '100%'
				}, 200);
				$(gameName[1]).animate({
					'right': '100%'
				}, 200);
				$(gameName[2]).animate({
					'right': '-20%'
				}, 200);
				$(gameName[3]).animate({
					'right': '-20%'
				}, 200);

				$(".multibet-win-notif").hide();

				createjs.Tween.get(this.bar).to({
					x: -360
				}, 200);
				createjs.Tween.get(this.multi_left).to({
					x: -360
				}, 200);

				createjs.Tween.get(this.bar2).to({
					x: this.context.stage.baseWidth
				}, 200);
				createjs.Tween.get(this.multi_right).to({
					x: this.context.stage.baseWidth
				}, 200);
			}

			for (var x = 0; x < this.games.length; x++) {
				if (visible) {
					if (!this.games[x].socketConnected) {
						this.games[x].connectToSocket();
					}
				} else {
					this.games[x].disconnectSocket();
				}
			}
		},
