    switch (this.roundphase) {
      case "flop":
        var flopBet = _.find(this.success_bet, function (e) {
          return e.table_id == 'flop';
        });
        if (!parseInt(flopBet.amount)) {
          this.flopFail();
        }
        break;

      case "turn":
        var turnBet = _.find(this.success_bet, function (e) {
          return e.table_id == 'turn';
        });
        if (!parseInt(turnBet.amount)) {
          this.turnFail();
        }
        break;

      case "river":
        var riverBet = _.find(this.success_bet, function (e) {
          return e.table_id == 'river';
        });
        if (!parseInt(riverBet.amount)) {
          this.riverFail();
        }
        break;
    }
